'use client'

import * as React from 'react'
import { ArrowRight, Xmark } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { bannerMesh } from '@/registry/satin/ui/banner'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * AnnouncementBar: one line of news across the top (or bottom) edge of the page, with a button
 * to read more and an optional close.
 *
 * `tone` sets the fill: primary (action/primary/bg, the default), inverse (action/inverse/bg) or
 * default (bg/card between two border/subtle rules). The bar is 44 high, the message centred in Body/lg with
 * the action after it, 12px apart: a secondary xs Button with a 14px arrow. The close button,
 * when `onDismiss` is passed, sits 12px from the right edge: a 28px square, the 16px cross at
 * 70% that turns full on hover over action/primary/bg-hover.
 *
 * `background="mesh"` adds the Banner's glow over the primary; `shimmer` sends a soft band of
 * light across now and then.
 *
 * `sticky` keeps it on the top or bottom edge of its scroll container as the page scrolls.
 * Long messages wrap; the close keeps its corner.
 */
export interface AnnouncementBarProps extends React.ComponentProps<'div'> {
  /** The button after the message; with `href` it renders as a link. */
  action?: { label: React.ReactNode; href?: string; onClick?: () => void }
  onDismiss?: () => void
  dismissLabel?: string
  /** Sticks to the top or bottom edge of its scroll container. */
  sticky?: 'top' | 'bottom'
  /**
   * `primary`: action/primary/bg (the default). `inverse`: action/inverse/bg, near-black in light
   * and near-white in dark. `default`: bg/card with border/subtle rules above and below, like a Banner.
   */
  tone?: 'primary' | 'inverse' | 'default'
  /** `mesh` lays the Banner's glow over the bar: lighter on primary and inverse, coloured on default. */
  background?: 'plain' | 'mesh'
  /** Now and then a soft band of light crosses the bar (off under reduced motion). */
  shimmer?: boolean
}

export function AnnouncementBar({
  action,
  onDismiss,
  dismissLabel = 'Dismiss announcement',
  sticky,
  tone = 'primary',
  background = 'plain',
  shimmer = false,
  children,
  className,
  ...props
}: AnnouncementBarProps) {
  const labels = useSatinLabels()
  const toneClass = {
    primary: 'sa:bg-action-primary-bg sa:text-action-primary-fg',
    inverse: 'sa:bg-action-inverse-bg sa:text-text-on-inverse',
    default: 'sa:bg-bg-card sa:text-text-default sa:[box-shadow:inset_0_1px_0_var(--border-subtle),inset_0_-1px_0_var(--border-subtle)]',
  }[tone]
  const closeClass = {
    primary: 'sa:text-action-primary-fg sa:opacity-70 sa:hover:bg-action-primary-bg-hover sa:hover:opacity-100',
    inverse: 'sa:text-text-on-inverse sa:opacity-70 sa:hover:bg-action-inverse-bg-hover sa:hover:opacity-100',
    default: 'sa:text-text-muted sa:hover:bg-bg-hover sa:hover:text-text-default',
  }[tone]
  const label = action && (
    <>
      {action.label}
      <ArrowRight aria-hidden />
    </>
  )

  return (
    <div
      role="region"
      aria-label={labels.announcement}
      data-slot="announcement-bar"
      data-tone={tone}
      className={cn(
        'sa:relative sa:isolate sa:flex sa:min-h-11 sa:w-full sa:items-center sa:justify-center sa:px-12 sa:py-2 sa:text-base',
        toneClass,
        shimmer && 'satin-sheen',
        sticky === 'top' && 'sa:sticky sa:top-0 sa:z-40',
        sticky === 'bottom' && 'sa:sticky sa:bottom-0 sa:z-40',
        className,
      )}
      {...props}
    >
      {background === 'mesh' && tone === 'default' && (
        <img
          src={bannerMesh.horizontal.one.light}
          alt=""
          aria-hidden
          className="sa:pointer-events-none sa:absolute sa:inset-0 sa:-z-10 sa:size-full sa:max-w-none sa:object-cover sa:mix-blend-multiply"
        />
      )}
      {background === 'mesh' && (
        <img
          src={bannerMesh.horizontal.one.dark}
          alt=""
          aria-hidden
          className="sa:pointer-events-none sa:absolute sa:inset-0 sa:-z-10 sa:size-full sa:max-w-none sa:object-cover sa:mix-blend-screen"
        />
      )}
      <div className="sa:flex sa:flex-wrap sa:items-center sa:justify-center sa:gap-x-3 sa:gap-y-1 sa:text-center">
        <p className="sa:m-0">{children}</p>
        {action &&
          (action.href ? (
            <Button asChild variant="secondary" size="xs" className="sa:shrink-0 sa:no-underline">
              <a href={action.href} onClick={action.onClick}>
                {label}
              </a>
            </Button>
          ) : (
            <Button variant="secondary" size="xs" className="sa:shrink-0" onClick={action.onClick}>
              {label}
            </Button>
          ))}
      </div>
      {onDismiss && (
        <button
          type="button"
          aria-label={dismissLabel}
          onClick={onDismiss}
          className={cn(
            'sa:absolute sa:top-1/2 sa:right-3 sa:grid sa:size-7 sa:-translate-y-1/2 sa:place-items-center sa:rounded-md sa:outline-none',
            closeClass,
            'sa:transition-[opacity,background-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
            'sa:focus-visible:opacity-100 sa:focus-visible:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
          )}
        >
          <Xmark aria-hidden className="sa:size-4 sa:[stroke-width:1.875]" />
        </button>
      )}
    </div>
  )
}
